/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field PrenotificationDaysFirst.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustDirectDebitMandatePrenotificationDaysFirst extends GUPPricingAttributeCustDirectDebitMandate implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, PrenotificationDaysFirst);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Integer);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by PrenotificationDaysFirst
    {
        if (! ret.in(custDirectDebitMandate.PrenotificationDaysFirst))
        {
            ret.add(custDirectDebitMandate.PrenotificationDaysFirst);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, PrenotificationDaysFirst));
    qbr.value(queryValue(_value));
}
